float3 boxMin = float3(CenterX - 300.0, CenterY - 300.0, GroundZ);
float3 uvw = (WorldPos - boxMin) / float3(600.0, 600.0, 300.0);
float h = WorldPos.z - GroundZ;
float inFog = (h >= 0.0 && h <= 240.0) ? 1.0 : 0.0;
float density = Texture3DSampleLevel(DensityVolume, DensityVolumeSampler, saturate(uvw), 0).a;
float keep = inFog * saturate(density);
return float4(ExtinctionPerM * keep, ExtinctionPerM * keep, ExtinctionPerM * keep, keep);
